import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/users.db')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT DEFAULT 'general'
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('svc_backup', 'backup@corp.internal', 'service', 'ops')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Supports partial matching."""
    dept = request.args.get('department', '')
    if not dept:
        return jsonify({'error': 'department parameter required'}), 400

    # Sanitize: remove semicolons and comments to prevent multi-statement injection
    dept_clean = dept.replace(';', '').replace('--', '').replace('/*', '')

    # Build query with LIKE for partial matching
    query = f"SELECT username, email, department FROM users WHERE department LIKE '%{dept_clean}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<username>', methods=['GET'])
def get_user(username):
    """Get user details by exact username match."""
    db = get_db()
    cursor = db.execute("SELECT username, email, role, department FROM users WHERE username = ?", (username,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user. Requires JSON body with username, email, department."""
    data = request.get_json()
    if not data or not all(k in data for k in ('username', 'email', 'department')):
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, department) VALUES (?, ?, ?)",
            (data['username'], data['email'], data['department'])
        )
        db.commit()
        return jsonify({'status': 'created', 'username': data['username']}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
